source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    best = None
    for color in {v for row in grid for v in row if v != background}:
        for r1 in range(h - 2):
            for r2 in range(r1 + 2, h):
                for c1 in range(w - 2):
                    for c2 in range(c1 + 2, w):
                        if (all(grid[r1][c] == color and grid[r2][c] == color for c in range(c1, c2 + 1)) and
                            all(grid[r][c1] == color and grid[r][c2] == color for r in range(r1, r2 + 1))):
                            area = (r2-r1-1)*(c2-c1-1)
                            if best is None or area > best[0]:
                                best = (area, r1, r2, c1, c2)
    out = [row[:] for row in grid]
    if best:
        _, r1, r2, c1, c2 = best
        for r in range(r1+1, r2):
            for c in range(c1+1, c2):
                out[r][c] = 4
    return out
